// F66 Svensk 404-sida: public/404.html finns, har noindex, inget skript, ingen spårning, tre absoluta länkar
// som leder till filer, AI-märkning och exakt text, står inte i sidkartan, och testet fångar fyra trasiga varianter.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const pub = 'public';
const fil = path.join(pub, '404.html');
const STYCKE1 = 'Adressen du skrev leder inte till någon sida hos oss. Kanske blev en bokstav fel på vägen. Här är tre ställen att gå vidare till.';
const STYCKE2 = 'Sidan sparar inga kakor, kör inga skript och hämtar inget från andra webbplatser.';

function harFil(h) {
  if (h === '/') return fs.existsSync(path.join(pub, 'index.html'));
  const v = h.replace(/^\//, '').replace(/\/$/, '');
  return fs.existsSync(path.join(pub, v + '.html')) || fs.existsSync(path.join(pub, v, 'index.html'));
}

function kontrollera(html) {
  const kod = html.replace(/<!--[\s\S]*?-->/g, '');
  const hrefs = [...kod.matchAll(/href="([^"]*)"/g)].map((m) => m[1]);
  const lankar = hrefs.filter((h) => !h.startsWith('#'));
  return {
    sidanFinns: /<html lang="sv">/.test(html) && /<meta charset="utf-8">/i.test(html) &&
      html.includes('<title>Sidan finns inte här – luminusloom.net</title>') &&
      html.includes('<h1>Sidan finns inte här</h1>') && hrefs.includes('#innehall') && /id="innehall"/.test(html),
    noindex: /<meta name="robots" content="noindex">/.test(html),
    ingetSkript: !/<script/i.test(kod) && !/\son[a-z]+\s*=/i.test(kod) &&
      !/<(img|iframe|object|embed|link)\b/i.test(kod) && !/(src|href)="(https?:)?\/\//i.test(kod) &&
      !/url\(/i.test(kod) && !/@import/i.test(kod),
    ingenSparning: !hrefs.some((h) => /[?&]/.test(h)) && !/cookie|localStorage|sessionStorage|utm_/i.test(kod),
    treLankar: ['/', '/marknad', '/sidkarta'].every((h) => hrefs.includes(h)),
    absolutaLankar: lankar.length > 0 && lankar.every((h) => h.startsWith('/') && !h.startsWith('//')),
    lankarnaFinns: lankar.length > 0 && lankar.every(harFil),
    ingaHtmlLankar: !hrefs.some((h) => /\.html(#|$)/.test(h)),
    aiMarkt: html.includes('AI-skapat') && html.includes('Generated by AI, Directed by MS'),
    text: html.includes(STYCKE1) && html.includes(STYCKE2),
  };
}

const html = fs.existsSync(fil) ? fs.readFileSync(fil, 'utf8') : '';
const krav = kontrollera(html);

// 11. Inte på sidkartan.
const karta = fs.readFileSync(path.join(pub, 'sidkarta.html'), 'utf8');
const kartTest = fs.readFileSync(path.join('tests', 'sidkarta.test.cjs'), 'utf8');
krav.intePaSidkartan = !karta.includes('href="/404"') && kartTest.includes("'404.html'");

// 12. Självprov: fyra trasiga varianter ska ge rött, originalet grönt.
const allaGrona = (k) => Object.values(k).every(Boolean);
const varianter = [
  html.replace('</main>', '<script>1</script></main>'),
  html.replace('href="/sidkarta"', 'href="sidkarta"'),
  html.replace('href="/marknad"', 'href="/marknad?utm_source=lapp"'),
  html.replace('<meta name="robots" content="noindex">', ''),
];
krav.testetFangar = html !== '' && allaGrona(kontrollera(html)) && varianter.every((v) => v !== html && !allaGrona(kontrollera(v)));

// 13. Sidkartans test är grönt.
krav.sidkartanGron = spawnSync(process.execPath, [path.join('tests', 'sidkarta.test.cjs')], { encoding: 'utf8' }).status === 0;

const ok = allaGrona(krav);
if (!ok) console.error('Röda: ' + Object.keys(krav).filter((k) => !krav[k]).join(', '));
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
